insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('math-ntuc-p4-0002', 'math-ntuc', 4, 'quest', 'Which number is a multiple of both 4 and 6?', '["18","24","30","20"]', 1, '24 is in the 4 times table (4 × 6) and the 6 times table (6 × 4).', '24 is a common multiple!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('math-ntuc-p4-0003', 'math-ntuc', 4, 'quest', 'There are 96 cans. They are packed 8 to a box. How many boxes are needed?', '["11","12","13","14"]', 1, '96 ÷ 8 = 12.', 'Twelve boxes!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('math-ntuc-p4-0004', 'math-ntuc', 4, 'quest', 'Auntie May buys 6 packs of pens at $4 each, then a notebook for $7. How much does she spend in all?', '["$31","$30","$28","$35"]', 0, '6 × $4 = $24, then $24 + $7 = $31. Two steps!', 'Thirty-one dollars in all!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('math-ntuc-p4-0005', 'math-ntuc', 4, 'quest', 'Estimate: 48 × 5 is closest to…', '["200","250","300","150"]', 1, '48 is about 50, and 50 × 5 = 250.', 'About 250 — close to the real 240!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('math-ntuc-p4-0006', 'math-ntuc', 4, 'fresh', '7 × 36 = ?', '["242","252","262","212"]', 1, '7 × 30 = 210 and 7 × 6 = 42, so 210 + 42 = 252.', '', 'bank') on conflict (id) do nothing;
