insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('math-ntuc-p4-0008', 'math-ntuc', 4, 'fresh', 'Which of these is a factor of 24?', '["7","8","9","11"]', 1, '24 ÷ 8 = 3 with nothing left over.', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('math-ntuc-p4-0009', 'math-ntuc', 4, 'fresh', 'A farmer packs 135 eggs into trays of 9. How many trays does he fill?', '["13","14","15","16"]', 2, '135 ÷ 9 = 15. 9 × 15 = 135.', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('math-ntuc-p4-0010', 'math-ntuc', 4, 'fresh', 'Ben buys 4 notebooks at $6 each and 2 pens at $3 each. How much does he spend in all?', '["$28","$30","$32","$26"]', 1, '4 × $6 = $24 and 2 × $3 = $6, then $24 + $6 = $30.', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('math-ntuc-p4-0011', 'math-ntuc', 4, 'fresh', 'What is the smallest multiple of 8 that is more than 50?', '["48","54","56","64"]', 2, 'Multiples of 8 go 48, 56… so 56 is the first one past 50.', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('math-ntuc-p4-0012', 'math-ntuc', 4, 'fresh', 'A shop sells 28 packets of rice a day. How many packets does it sell in 14 days?', '["382","392","402","372"]', 1, '28 × 14 = 392. 28 × 10 = 280 and 28 × 4 = 112.', '', 'bank') on conflict (id) do nothing;
