insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('math-ntuc-p4-0014', 'math-ntuc', 4, 'fresh', '5 × 48 = ?', '["230","240","250","200"]', 1, '5 × 48 = 240. 50 × 5 = 250, take away 2 × 5.', '', 'bank') on conflict (id) do nothing;
